import{_ as e,o as t,c as i,a2 as c}from"./chunks/framework.yo2CxoV2.js";const h=JSON.parse('{"title":"接入 GitBook","description":"","frontmatter":{},"headers":[],"relativePath":"publishing/gitbook.md","filePath":"publishing/gitbook.md","lastUpdated":1794228039000}'),a={name:"publishing/gitbook.md"};function d(l,o,r,s,n,p){return t(),i("div",null,[...o[0]||(o[0]=[c('<h1 id="接入-gitbook" tabindex="-1">接入 GitBook <a class="header-anchor" href="#接入-gitbook" aria-label="Permalink to &quot;接入 GitBook&quot;">​</a></h1><p>本公开仓库可以独立连接 GitBook，产品源码的可见性由原开发仓库继续管理。</p><h2 id="推荐-站点级-git-sync" tabindex="-1">推荐：站点级 Git Sync <a class="header-anchor" href="#推荐-站点级-git-sync" aria-label="Permalink to &quot;推荐：站点级 Git Sync&quot;">​</a></h2><ol><li>在 GitBook 中创建文档站点并连接 GitHub。</li><li>选择 <code>neekin/ordloom-docs</code>、<code>main</code> 分支，Project directory 使用仓库根目录。</li><li>采用仓库中的 <code>gitbook-docs.yaml</code>，将手册空间映射到 <code>./docs</code>。</li><li>首次同步选择以 GitHub 的手册内容为导入来源，确认导航后再发布站点。</li></ol><p>站点配置的 <code>ordloom-handbook</code> 是稳定空间 key。已有站点调整标题或 URL 时，不要随意改动该 key。</p><h2 id="单空间同步" tabindex="-1">单空间同步 <a class="header-anchor" href="#单空间同步" aria-label="Permalink to &quot;单空间同步&quot;">​</a></h2><p>根目录 <code>.gitbook.yaml</code> 指向 <code>./docs/</code>。如果界面要求直接映射空间目录，则选择 <code>docs</code>，使用其中的 <code>.gitbook.yaml</code>。</p><p>不要将 <code>docs</code> 同时当作映射目录、又重复设置为其下的内容 root；否则路径会错误地变成 <code>docs/docs</code>。</p><h2 id="内容约定" tabindex="-1">内容约定 <a class="header-anchor" href="#内容约定" aria-label="Permalink to &quot;内容约定&quot;">​</a></h2><ul><li><code>docs/README.md</code>：手册首页。</li><li><code>docs/SUMMARY.md</code>：导航，每个 Markdown 页面只出现一次。</li><li><code>docs/.gitbook/assets/</code>：文档图片。</li><li><code>examples/quickstart/</code>：可运行示例，通过公开 GitHub 链接从手册访问。</li></ul><p>修改后先运行 <code>python scripts/check_docs.py</code>，涉及示例时再执行示例测试，随后提交并推送。连接 Git Sync 后即可同步；本仓库没有预先绑定或伪造一个 GitBook 空间 ID。</p><p>首次连接的账号授权与最终站点地址由 GitBook 账号侧完成。</p><p>配置依据：<a href="https://gitbook.com/docs/docs-as-code/git-sync/content-configuration" target="_blank" rel="noreferrer">GitBook 官方 Content configuration</a>。</p>',13)])])}const b=e(a,[["render",d]]);export{h as __pageData,b as default};
